import json
with open('/app/resources/treasury_bulletin_2007_09.json', 'r') as f:
    data = json.load(f)

# Search for payroll employment data in the JSON structure
def search_json(obj, path=''):
    if isinstance(obj, dict):
        for key, value in obj.items():
            new_path = f'{path}.{key}' if path else key
            if 'payroll' in key.lower() or 'employment' in key.lower():
                print(f'Found at {new_path}: {value}')
            search_json(value, new_path)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            new_path = f'{path}[{i}]'
            search_json(item, new_path)

search_json(data)
